PLURALS = {
 "datetime_months_relative": {"one": "%1$d മാസം മുമ്പ്", "other": "%1$d മാസം മുമ്പ്"},
 "datetime_years_relative": {"one": "%1$d വർഷം മുമ്പ്", "other": "%1$d വർഷം മുമ്പ്"},
}


def xml_escape(text):
    # Escape & < > for XML. Apostrophes are inside quote-wrapped strings (we wrap in ").
    # Keep \n, \", „ etc. literal — they are Android escapes, not XML.
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')


def build_string_xml(key, value):
    return f'    <string name="{key}">"{xml_escape(value)}"</string>'


def build_plural_xml(key, forms):
    lines = [f'    <plurals name="{key}">']
    for qty, val in forms.items():
        lines.append(f'        <item quantity="{qty}">"{xml_escape(val)}"</item>')
    lines.append('    </plurals>')
    return '\n'.join(lines)


def main():
    with open(TARGET, 'r', encoding='utf-8') as f:
        content = f.read()

    replaced, inserted = [], []

    # 1. Replace existing <string> elements (single or multi-line).
    for key, value in STRINGS.items():
        new_el = build_string_xml(key, value).strip()
        # match whole <string name="key" ...>...</string> incl. possible attrs, multiline
        pattern = re.compile(
            r'[ \t]*<string name="' + re.escape(key) + r'"[^>]*>.*?</string>',
            re.DOTALL)
        repl = '    ' + new_el.lstrip()
        if pattern.search(content):
            content = pattern.sub(lambda m: repl, content, count=1)
            replaced.append(key)
        else:
            inserted.append((key, repl))

    # 2. Replace plurals.
    for key, forms in PLURALS.items():
        new_el = build_plural_xml(key, forms)
        pattern = re.compile(
            r'[ \t]*<plurals name="' + re.escape(key) + r'">.*?</plurals>',
            re.DOTALL)
        if pattern.search(content):
            content = pattern.sub(lambda m: new_el, content, count=1)
            replaced.append(key)
        else:
            inserted.append((key, new_el))

    # 3. Insert any not-yet-present elements before </resources> via rfind.
    if inserted:
        idx = content.rfind('</resources>')
        if idx == -1:
            raise RuntimeError("no </resources> found — file corrupt")
        block = '\n'.join(el for _, el in inserted) + '\n'
        content = content[:idx] + block + content[idx:]

    with open(TARGET, 'w', encoding='utf-8', newline='\n') as f:
        f.write(content)

    print("REPLACED:", len(replaced))
    print("INSERTED:", [k for k, _ in inserted])
    print("INSERTED_KEYS:", ",".join(k for k, _ in inserted))


if __name__ == '__main__':
    main()
